"""`index.md`: the wiki's orientation, generated by the host after each run, never by the model.

It opens with the number of open proposals, what the librarian is waiting on the owner for,
and a link to them. Then it lists each page as a link with its one-line summary, grouped by
type. Under each type the active pages come first, the most recently updated first, so what's
live is at the top; the rest follow by slug.
"""

from __future__ import annotations

from collections.abc import Iterable
from datetime import date
from pathlib import Path

from pa_core.librarian.wiki import (
    INDEX,
    PAGE_TYPES,
    PROPOSALS,
    Page,
    open_proposals,
    pages,
)


def render_index(listed: Iterable[Page], open_proposals: int = 0) -> str:
    """The index of `listed`: the count of `open_proposals`, with a link to them when there
    are any, then a section per page type that has pages, in `index_order`."""
    by_folder: dict[str, list[Page]] = {}
    for page in listed:
        by_folder.setdefault(page.folder, []).append(page)
    asked = f"Open proposals: {open_proposals}"
    if open_proposals:
        asked += f", in [[{PROPOSALS.removesuffix('.md')}]]"
    parts = ["# Index\n", f"{asked}\n"]
    for folder, page_type in PAGE_TYPES.items():
        group = sorted(by_folder.get(folder, ()), key=index_order)
        if group:
            entries = "".join(f"- [[{page.slug}]]: {page.summary}\n" for page in group)
            parts.append(f"## {page_type.heading}\n\n{entries}")
    if len(parts) == 2:
        parts.append("No pages yet.\n")
    return "\n".join(parts)


def index_order(page: Page) -> tuple[int, int, str]:
    """Where `page` sorts among its type's pages: active pages by `updated`, newest first
    (by slug within a day, and last without a date), then every other page by slug."""
    if not page.is_active:
        return (1, 0, page.slug)
    # A page whose `updated` is no date sorts last (lint fails such a page).
    return (0, -(page.updated or date.min).toordinal(), page.slug)


def write_index(tree: Path) -> None:
    """Regenerates `index.md` in the wiki at `tree` from its pages and its proposals."""
    text = render_index(pages(tree), len(open_proposals(tree)))
    (tree / INDEX).write_text(text, encoding="utf-8")
